/* ---- friction-free lead capture (Apply Now) ---- */
(function(){
  var modal = document.getElementById('leadModal');
  if (!modal) return;
  var form = document.getElementById('leadForm');
  var closeBtn = document.getElementById('leadClose');
  var lastFocus = null;
  function open(e){ if (e) e.preventDefault(); lastFocus = document.activeElement; modal.hidden = false; document.documentElement.style.overflow = 'hidden'; var f = document.getElementById('leadName'); if (f) f.focus(); }
  function close(){ modal.hidden = true; document.documentElement.style.overflow = ''; if (lastFocus) lastFocus.focus(); }
  document.querySelectorAll('.js-apply').forEach(function(a){ a.addEventListener('click', open); });
  closeBtn.addEventListener('click', close);
  modal.addEventListener('click', function(e){ if (e.target === modal) close(); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape' && !modal.hidden) close(); });
  form.addEventListener('submit', function(e){
    e.preventDefault();
    var name = document.getElementById('leadName').value.trim();
    var email = document.getElementById('leadEmail').value.trim();
    var phone = document.getElementById('leadPhone').value.trim();
    if (!name || !email || !phone) return;
    var text = 'Hi ONROL, I would like to apply for the next cohort.%0A%0AName: ' + encodeURIComponent(name) + '%0AEmail: ' + encodeURIComponent(email) + '%0APhone: ' + encodeURIComponent(phone);
    window.open('https://wa.me/918121306701?text=' + text, '_blank', 'noopener,noreferrer');
    close(); form.reset();
  });
})();

